import{readJsonValue}from"./chunk-etpksxq8.js";function catalogIntegerErrors(root,schema){let errors=new Set;function walk(node,rule,path){if(rule.$ref){if(!rule.$ref.startsWith("#/$defs/"))throw Error("Unsupported catalog schema reference");walk(node,schema.$defs[rule.$ref.slice(8)],path);return}if(rule.anyOf){for(let branch of rule.anyOf)walk(node,branch,path);return}if(node.kind==="number"&&(rule.type==="integer"||Array.isArray(rule.type)&&rule.type.includes("integer")))try{let value=readJsonValue(node.value,"json");if(typeof value!=="number"||!Number.isSafeInteger(value))throw Error("Not an exact integer")}catch{errors.add(path)}if(node.kind==="object"){for(let[key,value]of Object.entries(node.members))if(rule.properties&&Object.hasOwn(rule.properties,key))walk(value,rule.properties[key],path+"/"+key.replace(/~/g,"~0").replace(/\//g,"~1"))}if(node.kind==="array"&&rule.items)node.items.forEach((value,index)=>walk(value,rule.items,path+"/"+index))}return walk(root,schema,""),[...errors]}
export{catalogIntegerErrors};
